'use strict';
const $=s=>document.querySelector(s), app=$('#app'), KEY='life-sprint-214-v1';
const RANKS=[['Rookie',0],['Bronze',150],['Silver',400],['Gold',850],['Platinum',1400],['Diamond',2200]];
let state={xp:0,stats:{},sessions:[],active:null,prefs:{seconds:20,sound:true,motion:true},bestCombo:0}, storageOK=true,view='home',lessonTopic=0,toastTimer;
try{const saved=JSON.parse(localStorage.getItem(KEY));if(saved&&saved.stats&&Array.isArray(saved.sessions))state={...state,...saved};}catch(e){storageOK=false;}
state.prefs={seconds:20,sound:true,motion:true,...state.prefs};
if(![10,15,20].includes(state.prefs.seconds))state.prefs.seconds=20;
if(state.active&&!state.active.arcade){state.active=null;}
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const shuffle=a=>{a=[...a];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;};
const byId=id=>BANK.find(q=>q.id===id);
const misses=()=>BANK.filter(q=>state.stats[q.id]?.missed);
const rank=()=>RANKS.reduce((a,r)=>state.xp>=r[1]?r:a,RANKS[0]);
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch(e){storageOK=false;}chrome();}
function toast(s){clearTimeout(toastTimer);$('#toast').textContent=s;$('#toast').style.display='block';toastTimer=setTimeout(()=>$('#toast').style.display='none',3200);}
function chrome(){const r=rank(),next=RANKS[RANKS.indexOf(r)+1],percent=next?Math.max(0,Math.min(100,(state.xp-r[1])/(next[1]-r[1])*100)):100;$('#rank').innerHTML=`<div class="eyebrow">PRACTICE RANK</div><div class="rank-icon">◇</div><h3>${r[0]}</h3><div class="track"><i style="width:${percent}%"></i></div><div class="small muted">${state.xp} XP ${next?`· ${next[1]-state.xp} to ${next[0]}`:'· Top rank'}</div>`;$('#missBadge').textContent=misses().length||'';$('#saveNote').innerHTML=storageOK?'Progress saves on this browser.<br>No account needed.':'Storage unavailable. Keep this page open; progress may be lost.';document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));}
function stats(t){const qs=t===undefined?BANK:BANK.filter(q=>q.t===t);let n=0,c=0,seen=0;qs.forEach(q=>{const s=state.stats[q.id];if(s){n+=s.n;c+=s.c;seen++;}});return {n,c,seen,pct:n?Math.round(c/n*100):null};}
function go(v){document.body.classList.remove('danger-zone');view=v;chrome();if(v==='home')home();if(v==='learn')learn();if(v==='mistakes')mistakeView();if(v==='progress')progress();if(v==='sources')sources();if(v==='quiz')quiz();window.scrollTo(0,0);}
function home(){const s=stats();app.innerHTML=`<div class="topline"><div><div class="eyebrow">ARCADE TRAINING · EVERY SECOND COUNTS</div><h1>Beat the clock. Know the answer.</h1><p class="muted">Florida life, annuities & variable contracts.</p></div><span class="pill">${rank()[0]} · ${state.xp} XP</span></div><div class="stats"><div class="stat"><strong>${s.seen}<span> / ${BANK.length}</span></strong><span>Questions explored</span></div><div class="stat"><strong>${s.pct===null?'—':s.pct+'%'}</strong><span>Practice accuracy</span></div><div class="stat"><strong>${misses().length}</strong><span>To revisit</span></div></div>${state.active?`<div class="notice">You have an unfinished ${modeName(state.active.mode)} session. Timers continue while away.<div class="actions"><button class="btn" data-action="resume">Resume session</button><button class="btn secondary" data-action="discard">Discard session</button></div></div>`:''}${arcadeControls()}<section class="hero"><div><div class="eyebrow">15 QUESTIONS · ${state.prefs.seconds} SECONDS EACH</div><h2>Lock in.<br>Build your streak.</h2><p>Race a countdown on every question. Chain correct answers for combo XP. Learn the reason after each hit.</p><button class="btn dark" data-start="practice">Enter the arena ↗</button></div><div class="big-number" aria-hidden="true">2<br>14</div></section><div class="grid3"><section class="card mode"><div class="icon">◷</div><h3>5-minute sprint</h3><p>Race the clock through 20 questions. ${state.prefs.seconds} seconds per question, plus a five-minute round clock. Build a clean streak.</p><button class="btn secondary" data-start="sprint">Take the challenge</button></section><section class="card mode"><div class="icon">▤</div><h3>Boss run</h3><p>95 questions. ${state.prefs.seconds} seconds per question. Instant feedback. Target 85%+ accuracy.</p><button class="btn secondary" data-start="mock">Start boss run</button></section><section class="card mode"><div class="icon">↻</div><h3>Mistake lab</h3><p>Revisit missed concepts until you can explain why the answer is right.</p><button class="btn secondary" data-view="mistakes">Review ${misses().length} missed</button></section></div><div class="sectiontitle"><h2>Pick a topic to train</h2><span class="small muted">Percent = share of official outline</span></div><div class="topics">${TOPICS.map((t,i)=>`<button class="topic" data-topic="${i}"><span class="num">0${i+1}</span><span><b>${t[0]}</b><small>${stats(i).seen} of ${BANK.filter(q=>q.t===i).length} explored</small></span><span class="weight">${t[1]}%</span></button>`).join('')}</div><div class="notice"><b>Tonight's route:</b> Timed round → quick lessons for weak topics → mistake lab → one boss run. Use the sprint for recall, then leave time to sleep. This app is a focused practice aid, not a score guarantee or a replacement for your course.</div>`;}
function modeName(m){return ({practice:'training',sprint:'5-minute sprint',mock:'boss run',review:'mistake review',topic:'topic drill'})[m]||m;}
function weighted(counts){return shuffle(counts.flatMap((n,t)=>shuffle(BANK.filter(q=>q.t===t)).slice(0,n)));}
function start(mode,t){
 if(state.active){toast('Resume or discard your unfinished session first.');go('home');return;}
 let qs;if(mode==='mock')qs=weighted([17,17,13,9,23,16]);else if(mode==='review')qs=shuffle(misses()).slice(0,20);else if(mode==='topic')qs=shuffle(BANK.filter(q=>q.t===t)).slice(0,15);else if(mode==='sprint')qs=weighted([4,3,3,2,5,3]);else qs=weighted([3,3,2,1,3,3]);
 if(!qs.length){toast('No missed questions yet. Try a training round.');return;}
 state.active={arcade:true,mode,ids:qs.map(q=>q.id),orders:qs.map(()=>shuffle([0,1,2,3])),answers:qs.map(()=>null),index:0,start:Date.now(),deadline:mode==='sprint'?Date.now()+300000:null,qDeadline:Date.now()+state.prefs.seconds*1000,seconds:state.prefs.seconds,recorded:[],xpStart:state.xp,combo:0,bestCombo:0,lastXP:0};
 initAudio();sound('start');save();go('quiz');
}
function record(q,choice,m){
 const previousRank=rank()[0],s=state.stats[q.id]||{n:0,c:0,missed:false},a=state.active;s.n++;
 if(choice===0){s.c++;s.missed=false;if(a){a.combo++;a.bestCombo=Math.max(a.bestCombo,a.combo);state.bestCombo=Math.max(state.bestCombo||0,a.combo);}
 const base=m==='sprint'?15:10,chain=a?Math.min(15,Math.max(0,(a.combo-1)*3)):0,speed=a&&a.qDeadline-Date.now()>a.seconds*500?5:0;
 const gain=base+chain+speed;state.xp+=gain;if(a)a.lastXP=gain;
 }else{s.missed=true;if(a){a.combo=0;a.lastXP=0;}}
 state.stats[q.id]=s;if(rank()[0]!==previousRank){toast(`RANK UP · ${rank()[0]} unlocked!`);sound('rank');}
}
function quiz(){
 const a=state.active;if(!a){go('home');return;}if(a.deadline&&Date.now()>=a.deadline){finish(true);return;}
 const i=a.index,q=byId(a.ids[i]),selected=a.answers[i],locked=selected!==null;
 app.innerHTML=`<div class="question arcade-question"><div class="topline"><span class="pill">${modeName(a.mode)} · ${a.seconds}s / question</span><div class="audio-controls"><button class="mini" data-action="sound" aria-pressed="${state.prefs.sound}">${state.prefs.sound?'♫ Sound on':'♫ Sound off'}</button><button class="mini" data-action="motion" aria-pressed="${state.prefs.motion}">${state.prefs.motion?'FX on':'FX low'}</button></div></div>
 <div class="combat-hud"><div><span class="eyebrow">QUESTION ${i+1} / ${a.ids.length}</span><div id="clock" class="clock" role="timer" aria-label="Question time remaining"></div></div><div class="combo ${a.combo>=3?'on-fire':''}"><span class="eyebrow">${a.combo>=5?'ON FIRE':a.combo>=3?'COMBO ACTIVE':'STREAK'}</span><strong>${a.combo}<small> CHAIN</small></strong></div><div><span class="eyebrow">ROUND XP</span><strong class="xp-counter">+${state.xp-a.xpStart}</strong></div></div>
 <div class="fuse" role="progressbar" aria-label="Question time remaining" aria-valuemin="0" aria-valuemax="${a.seconds}"><i id="timeFill"></i></div>
 <div class="topline small muted"><span>${TOPICS[q.t][0]}</span><span id="roundClock">${a.deadline?'':''}</span></div>
 <h1 class="qtitle">${esc(q.q)}</h1><div class="answers">${a.orders[i].map((opt,pos)=>`<button class="answer ${selected===opt?'selected':''} ${locked&&opt===0?'correct':''} ${locked&&selected===opt&&opt!==0?'wrong':''}" data-answer="${opt}" ${locked?'disabled':''}><span class="letter">${'ABCD'[pos]}</span><span>${esc(q.options[opt])}${locked&&opt===0?' ✓':''}</span></button>`).join('')}</div>
 ${locked?`<div class="feedback ${selected===0?'':'bad'}" role="status"><h3>${selected===0?`${a.combo>=5?'ON FIRE':a.combo>=3?'COMBO':'NICE HIT'} · +${a.lastXP} XP`:selected===-1?'TIME OUT · Streak broken':'MISFIRE · Streak broken'}</h3>${selected!==0?`<p><b>${esc(q.options[0])}</b></p>`:''}<p>${esc(q.why)}</p><span class="small muted">Lock in the idea. The next countdown starts when you continue.</span></div>`:''}
 <div class="actions"><button class="btn secondary" data-view="home">Save & leave</button><span class="spacer"></span><button class="btn" data-action="next" ${!locked?'disabled':''}>${i===a.ids.length-1?'Finish run':'Next challenge →'}</button></div><p class="small muted">${locked?'Correct answers build your streak. Mistakes return in the lab.':'A timeout counts as a miss. The clock keeps running if you leave.'}</p></div>`;
 tick();
}
function tick(){
 const a=state.active;if(!a)return;
 if(a.deadline&&Date.now()>=a.deadline){finish(true);return;}
 const locked=a.answers[a.index]!==null;
 if(!locked&&Date.now()>=a.qDeadline){answer(-1);return;}
 const remain=Math.max(0,a.qDeadline-Date.now()),sec=Math.ceil(remain/1000),el=$('#clock'),fill=$('#timeFill');
 if(el)el.textContent=locked?'LOCKED':`${(remain/1000).toFixed(1)}s`;
 if(fill)fill.style.width=(locked?0:remain/(a.seconds*1000)*100)+'%';
 const bar=$('.fuse');if(bar)bar.setAttribute('aria-valuenow',locked?0:sec);
 const danger=!locked&&sec<=5&&view==='quiz';document.body.classList.toggle('danger-zone',danger);
 if(el)el.classList.toggle('urgent',danger);
 const rc=$('#roundClock');if(rc&&a.deadline){const r=Math.max(0,Math.ceil((a.deadline-Date.now())/1000));rc.textContent=`Round ${Math.floor(r/60)}:${String(r%60).padStart(2,'0')}`;}
 if(danger&&lastBeep!==`${a.index}-${sec}`){lastBeep=`${a.index}-${sec}`;sound('tick',sec);}
}
function answer(choice){
 const a=state.active;if(!a||a.answers[a.index]!==null||Date.now()<impactUntil)return;
 if(a.deadline&&Date.now()>=a.deadline){finish(true);return;}
 if(Date.now()>=a.qDeadline)choice=-1;
 a.answers[a.index]=choice;record(byId(a.ids[a.index]),choice,a.mode);a.recorded.push(a.index);save();
 if(view==='quiz'){quiz();impact(choice===0,choice===-1);}else if(view==='home'){home();toast('Question timed out. Resume to review the explanation.');}
}
function finish(expired=false){document.body.classList.remove('danger-zone');const a=state.active;if(!a)return;const before=a.xpStart; a.ids.forEach((id,i)=>{if(!a.recorded.includes(i)&&(a.answers[i]!==null||a.mode==='mock'))record(byId(id),a.answers[i],a.mode);});const result={mode:a.mode,ids:a.ids,answers:a.answers,date:new Date().toISOString(),correct:a.answers.filter(v=>v===0).length,total:a.mode==='sprint'?a.answers.filter(v=>v!==null).length:a.ids.length,available:a.ids.length,bestCombo:a.bestCombo||0,xp:state.xp-before,expired};state.sessions.unshift(result);state.sessions=state.sessions.slice(0,20);state.active=null;save();view='result';chrome();results(result);sound('finish');window.scrollTo(0,0);}
function results(r){const pct=r.total?Math.round(r.correct/r.total*100):0;app.innerHTML=`<div class="eyebrow">${r.expired?'TIME IS UP':'ROUND COMPLETE'} · ${modeName(r.mode)}</div><h1>${pct>=85?'Strong round. Keep it consistent.':pct>=70?'Good progress. Close the gaps.':'You found what to work on.'}</h1><div class="card"><div class="topline"><div><div class="resultscore">${pct}%</div><p>${r.correct} / ${r.total} correct${r.mode==='sprint'?` · ${r.total} of ${r.available} attempted`:''}</p></div><span class="pill">+${r.xp} XP · ${r.bestCombo||0} best streak</span></div><p class="muted">${r.mode==='mock'?'Aim for repeated 85%+ practice scores as a buffer. This is a study target, not a prediction of your licensing score.':'Read the explanation for anything you missed, then test yourself again.'}</p><div class="actions"><button class="btn" data-start="review" ${misses().length?'':'disabled'}>Train missed questions</button><button class="btn secondary" data-view="home">Back to training</button></div></div><div class="sectiontitle"><h2>Answer review</h2><span class="small muted">${r.mode==='mock'?'All questions':'Your round'}</span></div>${r.ids.map((id,i)=>{const q=byId(id),a=r.answers[i];return `<div class="reviewitem"><h3>${i+1}. ${esc(q.q)}</h3><p class="${a===0?'righttext':'wrongtext'}">${a===null?'Not answered':a===-1?'Time expired':`Your answer: ${esc(q.options[a])}`}${a===0?' ✓':''}</p>${a!==0?`<p class="righttext">Correct: ${esc(q.options[0])}</p>`:''}<p class="muted">${esc(q.why)}</p></div>`;}).join('')}`;}
function learn(){app.innerHTML=`<div class="eyebrow">UNDERSTAND FIRST. MEMORIZE LESS.</div><h1>Quick lessons</h1><p class="muted">Open a question to see the answer and a simple explanation.</p><label for="lessonSelect" class="small">Choose a topic</label><br><select id="lessonSelect">${TOPICS.map((t,i)=>`<option value="${i}" ${i===lessonTopic?'selected':''}>${t[0]} · ${t[1]}%</option>`).join('')}</select><section class="card lesson"><div class="lessonhead"><h2>${TOPICS[lessonTopic][0]}</h2><p class="muted">${TOPICS[lessonTopic][2]}</p><button class="btn" data-topic="${lessonTopic}">Quiz me on this topic</button></div>${BANK.filter(q=>q.t===lessonTopic).map(q=>`<details><summary>${esc(q.q)}</summary><p><b>${esc(q.options[0])}.</b> ${esc(q.why)}</p></details>`).join('')}</section>`;$('#lessonSelect').onchange=e=>{lessonTopic=Number(e.target.value);learn();};}
function mistakeView(){const m=misses();app.innerHTML=`<div class="eyebrow">MISTAKES ARE YOUR STUDY PLAN</div><h1>Mistake lab <span class="muted">/ ${m.length}</span></h1><p class="muted">A correct answer in a later drill clears that question from this list.</p><button class="btn" data-start="review" ${m.length?'':'disabled'}>Train ${Math.min(m.length,20)} missed questions</button>${m.length?m.map(q=>`<div class="reviewitem"><span class="pill">${TOPICS[q.t][0]}</span><h3 style="margin-top:14px">${esc(q.q)}</h3><p class="righttext">${esc(q.options[0])}</p><p class="muted">${esc(q.why)}</p></div>`).join(''):'<div class="notice">Nothing to revisit yet. Start a training round to find your weak spots.</div>'}`;}
function progress(){app.innerHTML=`<div class="eyebrow">EFFORT EARNS RANK. ACCURACY SHOWS LEARNING.</div><h1>Your progress</h1><div class="card"><div class="topline"><h2>${rank()[0]}</h2><span class="pill">${state.xp} XP</span></div><p class="muted">Correct: 10 XP (15 in Sprint), plus up to 15 streak XP and 5 speed XP. Wrong or timeout breaks the streak; earned XP stays. Ranks measure practice, not exam readiness.</p><div class="roadmap">${RANKS.map(r=>`<span class="${state.xp>=r[1]?'unlocked':''}">${r[0]} · ${r[1]}</span>`).join('')}</div></div><div class="sectiontitle"><h2>Where to focus next</h2></div>${TOPICS.map((t,i)=>{const s=stats(i);return `<div class="reviewitem"><div class="topline"><b>${t[0]}</b><span>${s.pct===null?'Unseen':s.pct+'%'}</span></div><div class="track"><i style="width:${s.pct||0}%"></i></div><span class="small muted">${s.n} answers · ${s.seen} unique questions seen</span></div>`;}).join('')}<div class="sectiontitle"><h2>Recent rounds</h2></div>${state.sessions.length?state.sessions.map((r,i)=>`<button class="topic" data-result="${i}" style="width:100%;margin-bottom:10px"><span><b>${modeName(r.mode)}</b><small>${new Date(r.date).toLocaleDateString()} · ${r.correct}/${r.total} correct</small></span><span class="weight">${r.total?Math.round(r.correct/r.total*100):0}%</span></button>`).join(''):'<p class="muted">Finish a round to see your results here.</p>'}`;}
function sources(){app.innerHTML=`<div class="eyebrow">FLORIDA 2–14 · LIFE ONLY</div><h1>Know the exam</h1><div class="card"><h2>95 questions · 2 hours</h2><p>The official 2026 outline lists 85 scored questions plus 10 unscored pretest questions. You won't know which are unscored. Answer every question. The published passing score is 70%; 85%+ is our higher practice target.</p><p class="muted">Our boss run uses 95 original questions with approximately the outline's topic proportions, a 10–20 second question timer, and instant feedback. This is deliberately faster than the official exam, not a timing simulation or complete course.</p><table><thead><tr><th>Section</th><th>Weight</th></tr></thead><tbody>${TOPICS.map(t=>`<tr><td>${t[0]}</td><td>${t[1]}%</td></tr>`).join('')}</tbody></table></div><div class="sectiontitle"><h2>Numbers worth separating</h2></div><div class="card"><p><b>14 days:</b> ordinary nonreplacement life free look after delivery.</p><p><b>21 days:</b> annuity free look.</p><p><b>At least 30 days:</b> individual life premium grace period after the first premium.</p><p><b>31 days:</b> eligible group life conversion application and first premium.</p><p><b>Within 3 years:</b> life reinstatement after premium default, subject to conditions.</p><p class="small muted">Read the question's context. Special contracts and replacement situations can have additional rules.</p></div><div class="sectiontitle"><h2>Official references</h2></div><p class="muted small">Checked September 27, 2026. Questions and explanations are original study material. Use your course for topics and details beyond this focused bank.</p><ul class="sources"><li><a target="_blank" rel="noopener" href="https://www.pearsonvue.com/content/dam/VUE/vue/en/documents/publications/121003.pdf">Pearson VUE · 2026 Florida content outline (first 3 pages)</a></li><li><a target="_blank" rel="noopener" href="https://www.pearsonvue.com/content/dam/VUE/vue/en/documents/publications/121000.pdf">Pearson VUE · Candidate handbook and test-day rules</a></li><li><a target="_blank" rel="noopener" href="https://www.myfloridacfo.com/division/consumers/understanding-insurance/lifeinsuranceoverview">Florida DFS · Life insurance overview</a></li><li><a target="_blank" rel="noopener" href="https://myfloridacfo.com/division/consumers/understanding-insurance/annuityoverview">Florida DFS · Annuity overview</a></li><li><a target="_blank" rel="noopener" href="https://content.naic.org/insurance-topics/life-insurance">NAIC · Life insurance</a></li>${['627.453','627.455','627.459','627.566','627.4554','626.9541','626.572','626.551','626.431'].map(s=>`<li><a target="_blank" rel="noopener" href="https://www.flsenate.gov/Laws/Statutes/2026/${s}">Florida Statutes § ${s}</a></li>`).join('')}</ul><div class="notice">Before test day: confirm your appointment time, location, identification requirements, and check-in instructions in your booking and candidate handbook. Practice scores do not guarantee a licensing result.</div>`;}

let audioContext=null,impactUntil=0,lastBeep='',impactTimer,fxTimer;
const systemReduced=window.matchMedia&&window.matchMedia('(prefers-reduced-motion: reduce)').matches;
function applyMotion(){document.body.classList.toggle('low-motion',!state.prefs.motion||!!systemReduced);}
function arcadeControls(){return `<div class="arcade-settings"><div><span class="eyebrow">CHOOSE YOUR PRESSURE</span><div class="difficulty">${[[20,'Charged'],[15,'Overdrive'],[10,'Blitz']].map(([n,label])=>`<button class="mini ${state.prefs.seconds===n?'chosen':''}" data-seconds="${n}" aria-pressed="${state.prefs.seconds===n}">${n}s · ${label}</button>`).join('')}</div></div><div class="audio-controls"><button class="mini" data-action="sound" aria-pressed="${state.prefs.sound}">${state.prefs.sound?'♫ Sound on':'♫ Sound off'}</button><button class="mini" data-action="motion" aria-pressed="${state.prefs.motion}">${state.prefs.motion?'FX on':'FX low'}</button></div></div>`;}
function initAudio(){if(!state.prefs.sound)return;try{const AC=window.AudioContext||window.webkitAudioContext;if(!AC)return;if(!audioContext)audioContext=new AC();if(audioContext.state==='suspended')audioContext.resume().catch(()=>{});}catch(e){}}
function tone(freq,at,duration,type='sine',volume=.06){if(!audioContext||audioContext.state!=='running')return;const o=audioContext.createOscillator(),g=audioContext.createGain();o.type=type;o.frequency.value=freq;g.gain.setValueAtTime(0,at);g.gain.linearRampToValueAtTime(volume,at+.008);g.gain.exponentialRampToValueAtTime(.001,at+duration);o.connect(g);g.connect(audioContext.destination);o.start(at);o.stop(at+duration+.02);}
function sound(kind,n=0){if(!state.prefs.sound||!audioContext||audioContext.state!=='running')return;const t=audioContext.currentTime;try{
 if(kind==='tick'){tone(n<=2?880:440,t,.065,'sine',.04);return;}
 if(kind==='wrong'||kind==='timeout'){tone(130,t,.16,'triangle',.1);tone(75,t+.12,.22,'sine',.11);return;}
 const notes=kind==='rank'?[523,659,784,1047,1319]:kind==='finish'?[392,523,659,784]:kind==='start'?[196,294,392]:kind==='combo'?[659,831,988,1319]:[523,659,880];
 notes.forEach((f,i)=>tone(f,t+i*.075,.19,'triangle',.065));
 }catch(e){}}
function impact(correct,timeout){
 clearTimeout(impactTimer);clearTimeout(fxTimer);document.body.classList.remove('hit-good','hit-bad','hit-stop');void document.body.offsetWidth;
 const q=$('.arcade-question');if(q){q.classList.remove('recoil-good','recoil-bad');void q.offsetWidth;q.classList.add(correct?'recoil-good':'recoil-bad');}
 document.body.classList.add(correct?'hit-good':'hit-bad');
 if(!correct){impactUntil=Date.now()+220;document.body.classList.add('hit-stop');impactTimer=setTimeout(()=>document.body.classList.remove('hit-stop'),160);}
 sound(correct?(state.active?.combo>=3?'combo':'right'):timeout?'timeout':'wrong');
 const fx=$('#impactText');if(fx){fx.textContent=correct?(state.active.combo>=3?`${state.active.combo}× COMBO`:'NICE HIT'):timeout?'TIME OUT':'MISFIRE';fx.className=correct?'burst good':'burst bad';}
 fxTimer=setTimeout(()=>{document.body.classList.remove('hit-good','hit-bad');if(fx)fx.className='burst';},850);
}
document.body.insertAdjacentHTML('beforeend','<div id="impactText" class="burst" aria-hidden="true"></div>');
document.addEventListener('click',e=>{
 const b=e.target.closest('button,a.brand');if(!b||b.disabled)return;
 if(Date.now()<impactUntil)return;
 initAudio();
 if(b.matches('a.brand')){e.preventDefault();go('home');return;}
 if(b.dataset.seconds!==undefined){state.prefs.seconds=Number(b.dataset.seconds);save();sound('start');home();return;}
 if(b.dataset.action==='sound'){state.prefs.sound=!state.prefs.sound;initAudio();save();if(state.prefs.sound)sound('right');if(view==='quiz')quiz();else if(view==='home')home();return;}
 if(b.dataset.action==='motion'){state.prefs.motion=!state.prefs.motion;applyMotion();save();if(view==='quiz')quiz();else if(view==='home')home();return;}
 if(b.dataset.view){go(b.dataset.view);return;}
 if(b.dataset.start){start(b.dataset.start);return;}
 if(b.dataset.topic!==undefined){start('topic',Number(b.dataset.topic));return;}
 if(b.dataset.result!==undefined){view='result';results(state.sessions[Number(b.dataset.result)]);window.scrollTo(0,0);return;}
 const a=state.active;
 if(b.dataset.answer!==undefined&&a){answer(Number(b.dataset.answer));return;}
 switch(b.dataset.action){
 case 'resume':go('quiz');break;
 case 'discard':if(confirm('Discard this unfinished session? Completed answers and earned XP stay saved.')){state.active=null;save();go('home');}break;
 case 'next':if(!a||a.answers[a.index]===null)return;if(a.index<a.ids.length-1){a.index++;a.qDeadline=Date.now()+a.seconds*1000;save();sound('start');quiz();window.scrollTo(0,0);}else finish();break;
 }
});
setInterval(tick,100);document.addEventListener('visibilitychange',tick);applyMotion();go('home');
